        *s++ = __PKHTB(acc_q, acc_i, 16);
#endif

        x2 = x1;
        x1 = x0;
    }
    fm_demod_state.pre1 = x1;
    fm_demod_state.pre2 = x2;
}

void
fm_demod0(int16_t *src, int16_t *dst, size_t len)
{
    int32_t *s = __SIMD32(src);
	uint32_t x0 = fm_demod_state.last;
	unsigned int i;

	for (i = 0; i < len; i += 2) {
        uint32_t x1 = *s++;
        *dst++ = atan_2iq(x0, x1);
		x0 = x1;
	}
	fm_demod_state.last = x0;
}

